<script setup lang="ts">
/**
 * A default command plus a menu of variants (`design/components/split-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/split-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, provide, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/menu'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  Icon,
  agentMember,
  agentPress,
  chooseMenuEntry,
  followHighlight,
  menuChoices,
  useDirection,
  useMediaQuery,
  type IconRole,
  type LawfulVariants,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/split-button.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import Kbd from '../structure/Kbd.vue'
import SplitButtonSubmenu from './SplitButtonSubmenu.vue'
import type { MenuEntry } from '../overlays/Menu.vue'

export interface SplitButtonGrid {
  solid: 'accent'
  soft: 'accent'
  outline: 'neutral' | 'accent'
}

export type SplitButtonAppearance = LawfulVariants<SplitButtonGrid>

export interface SplitButtonProps {
  /**
   * Opens on mount. For galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  /**
   * Disables the whole group, because the halves never differ.
   */
  disabled?: boolean
  /**
   * Menu entries exactly as `menu.md` defines them, with every entry kind supported.
   */
  entries: MenuEntry[]
  /**
   * A leading icon on the primary half (as in Button).
   */
  icon?: IconRole
  /**
   * The primary half's visible text, as in Button, truncated with an ellipsis on overflow.
   */
  label: string
  /**
   * Shows the spinner in the primary half's icon slot, following the conventions' loading rule,
   * and the layout stays the same. The chevron is disabled too. One running command is the whole
   * group's state, and starting a variant while it runs would be the double-submit bug Button
   * prevents, at group level.
   */
  loading?: boolean
  /**
   * The chevron half's accessible name ("More resolve options"). It is `iconOnly`, and an
   * unnamed second button would be an unexplained tab stop. Required, because the member has no
   * built-in text (as with PasswordInput's `toggleLabel`).
   */
  menuLabel: string
  /**
   * The menu half's presentation, as in Menu (`menu.md`; the conventions' sheet presentation).
   * `'auto'` shows the panel as a sheet below `30rem`, and `'popover'` keeps the popper. The
   * control group itself never changes, because the halves are Buttons, and Buttons have no
   * phone-specific form.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  tone?: 'accent' | 'neutral'
  variant?: 'solid' | 'soft' | 'outline'
}

defineOptions({ name: 'SplitButton', inheritAttrs: false })

const props = withDefaults(defineProps<SplitButtonProps>(), {
  defaultOpen: undefined,
  disabled: false,
  loading: false,
  presentation: 'auto',
  size: 'md',
  tone: 'accent',
  variant: 'solid',
})
const emit = defineEmits<{ click: [event: MouseEvent] }>()
const uid = useId()
const panel = useTemplateRef<HTMLElement>('panel')
const primary = useTemplateRef<HTMLElement>('primary')
const scrim = useTemplateRef<HTMLElement>('scrim')
const sheetPanel = useTemplateRef<HTMLElement>('sheetPanel')
const phone = useMediaQuery('phone')
const sheeting = computed(() => props.presentation === 'auto' && phone.value)
const flat = computed(() =>
  props.entries.flatMap((entry) =>
    entry.kind === 'submenu'
      ? [{ kind: 'label' as const, label: entry.label }, ...(entry.disabled ? [] : entry.items)]
      : [entry],
  ),
)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    defaultOpen: props.defaultOpen,
    disabled: props.disabled || props.loading,
    positioning: { placement: 'bottom-end', gutter: 2 },
    onSelect: (details) => {
      flat.value.forEach(
        (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
      )
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const present = usePresence(() => api.value.open && !sheeting.value, panel)
const sheetPresent = usePresence(
  () => api.value.open && sheeting.value,
  sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(() => api.value.open && sheeting.value, scrim, 'dialog.scrim')
provide('polymorph:SplitButton', {
  get api() {
    return api.value
  },
  get service() {
    return service
  },
})
const effect1 = () => {
  followHighlight(panel.value, api.value.highlightedValue)
}
onMounted(effect1)
watch(() => api.value.highlightedValue, effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'SplitButton',
    element: () => primary.value,
    state: () => ({
      disabled: props.disabled,
      loading: props.loading,
      open: api.value.open,
      entries: menuChoices(props.entries),
    }),
    actions: {
      press: () => agentPress(primary.value),
      choose: {
        argument: 'id',
        run: (value) =>
          (() => {
            if (props.loading)
              throw new Error('A command is running; its variants wait until it ends.')
            if (chooseMenuEntry(props.entries, value) && api.value.open) api.value.setOpen(false)
          })(),
      },
      open: () =>
        (() => {
          if (props.loading)
            throw new Error('A command is running; its variants wait until it ends.')
          api.value.setOpen(true)
        })(),
      close: () => api.value.setOpen(false),
    },
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <span
    :class="styles.group"
    :data-variant="variant"
    :data-tone="tone"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    data-member="split-button"
  >
    <!-- primary -->
    <button
      ref="primary"
      :class="styles.primary"
      type="button"
      :disabled="disabled"
      :aria-busy="loading ? true : undefined"
      :data-variant="variant"
      :data-tone="tone"
      :data-size="size"
      :data-disabled="disabled ? '' : undefined"
      :data-state="loading ? 'loading' : undefined"
      @click="!loading && emit('click', $event)"
    >
      <span v-if="loading" :class="styles.spinner">
        <Icon name="loading" :size="size" />
      </span>
      <span v-else-if="icon !== undefined" :class="styles.glyph">
        <Icon :name="icon" :size="size" />
      </span>
      <span :class="styles.label">
        {{ label }}
      </span>
    </button>
    <span :class="styles.seam" aria-hidden="true" />
    <!-- trigger -->
    <button
      v-bind="api.getTriggerProps()"
      :class="styles.chevron"
      :disabled="disabled || loading"
      :aria-label="menuLabel"
      :data-variant="variant"
      :data-tone="tone"
      :data-size="size"
      :data-disabled="disabled ? '' : undefined"
      data-icon-only=""
    >
      <Icon name="expand" :size="size" />
    </button>
  </span>
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.content"
        :style="{
          '--radix-dropdown-menu-content-available-height': 'var(--available-height)',
          '--radix-dropdown-menu-content-transform-origin': 'var(--transform-origin)',
        }"
        :hidden="undefined"
        data-member="split-button"
        @focus="followHighlight(panel, api.highlightedValue)"
      >
        <template v-for="(entry, index) in entries" :key="index">
          <div
            v-if="entry.kind === 'separator'"
            v-bind="api.getSeparatorProps()"
            :class="styles.separator"
          />
          <div v-else-if="entry.kind === 'label'" :class="styles.groupLabel">
            {{ entry.label }}
          </div>
          <div
            v-else-if="entry.kind === 'checkbox'"
            v-bind="
              api.getOptionItemProps({
                type: 'checkbox',
                value: entry.label,
                checked: entry.checked,
                disabled: entry.disabled,
                closeOnSelect: false,
                onCheckedChange: entry.onCheckedChange,
              })
            "
            :class="[styles.item, styles.checkbox]"
            tabindex="-1"
            @focus="api.setHighlightedValue(entry.label)"
          >
            <span :class="styles.check">
              <Icon v-if="entry.checked" name="confirm" size="sm" />
            </span>
            <span :class="styles.rowLabel">
              {{ entry.label }}
            </span>
          </div>
          <SplitButtonSubmenu v-else-if="entry.kind === 'submenu'" :entry="entry" />
          <div
            v-else
            v-bind="api.getItemProps({ value: entry.label, disabled: entry.disabled })"
            :class="styles.item"
            :data-tone="entry.tone ?? 'neutral'"
            tabindex="-1"
            @focus="api.setHighlightedValue(entry.label)"
          >
            <span v-if="entry.icon !== undefined" :class="styles.rowGlyph">
              <Icon :name="entry.icon" size="sm" />
            </span>
            <span :class="styles.rowLabel">
              {{ entry.label }}
            </span>
            <span v-if="entry.kbd !== undefined" :class="styles.hint">
              <Kbd>
                {{ entry.kbd }}
              </Kbd>
            </span>
          </div>
        </template>
      </div>
    </div>
    <div
      v-if="scrimPresent"
      ref="scrim"
      :class="sheet.scrim"
      :data-state="api.open ? 'open' : 'closed'"
    />
    <div v-if="sheetPresent" :class="sheet.positioner">
      <div
        ref="sheetPanel"
        :class="sheet.panel"
        data-presentation="sheet"
        :data-state="api.open ? 'open' : 'closed'"
        tabindex="-1"
      >
        <!-- panel -->
        <div
          ref="panel"
          v-bind="api.getContentProps()"
          :class="styles.sheetList"
          :hidden="undefined"
          data-member="split-button"
          @focus="followHighlight(panel, api.highlightedValue)"
        >
          <template v-for="(entry, index) in flat" :key="index">
            <div
              v-if="entry.kind === 'separator'"
              v-bind="api.getSeparatorProps()"
              :class="styles.separator"
            />
            <div v-else-if="entry.kind === 'label'" :class="styles.groupLabel">
              {{ entry.label }}
            </div>
            <div
              v-else-if="entry.kind === 'checkbox'"
              v-bind="
                api.getOptionItemProps({
                  type: 'checkbox',
                  value: entry.label,
                  checked: entry.checked,
                  disabled: entry.disabled,
                  closeOnSelect: false,
                  onCheckedChange: entry.onCheckedChange,
                })
              "
              :class="[styles.item, styles.checkbox]"
              tabindex="-1"
              @focus="api.setHighlightedValue(entry.label)"
            >
              <span :class="styles.check">
                <Icon v-if="entry.checked" name="confirm" size="sm" />
              </span>
              <span :class="styles.rowLabel">
                {{ entry.label }}
              </span>
            </div>
            <div
              v-else
              v-bind="api.getItemProps({ value: entry.label, disabled: entry.disabled })"
              :class="styles.item"
              :data-tone="entry.tone ?? 'neutral'"
              tabindex="-1"
              @focus="api.setHighlightedValue(entry.label)"
            >
              <span v-if="entry.icon !== undefined" :class="styles.rowGlyph">
                <Icon :name="entry.icon" size="sm" />
              </span>
              <span :class="styles.rowLabel">
                {{ entry.label }}
              </span>
              <span v-if="entry.kbd !== undefined" :class="styles.hint">
                <Kbd>
                  {{ entry.kbd }}
                </Kbd>
              </span>
            </div>
          </template>
        </div>
      </div>
    </div>
  </Teleport>
</template>
